public static void main(String[] args){
    var sc = new Scanner(System.in);
    String word = sc.nextLine();
    int[] frequency = new int[26];
    for(int x = 0; x < word.length(); x++){
        frequency[word.charAt(x) - 'a']++;
    }
    long totalSwaps = (long)word.length() * (word.length() - 1) / 2;
    long nonDistinctSwaps = 0;
    for(int count : frequency){
        if(count >= 2){
            nonDistinctSwaps += (long)count * (count - 1) / 2;
        }
    }
    long distinctSwaps = totalSwaps - nonDistinctSwaps;
    if(nonDistinctSwaps < totalSwaps) {
        distinctSwaps++;
    }
    System.out.println(distinctSwaps);
}
